#!/usr/bin/env node
/**
 * OMNIFLOW — setup/patch file (single file, zero arguments).
 *
 *         node omniflow-setup.mjs
 *
 * Kis repo mein chalao:
 *   - WEBSITE repo root (jahan package.json hai)    -> website files + sidebar patch
 *   - BACKEND repo root (jahan app.py hai)          -> backend files + app.py patch
 *
 * Agar website aur backend dono repos aik hi folder ke ANDAR hain, to sirf
 * aik baar chalao — script doosri repo khud dhoondh kar patch kar dega.
 *
 * Optional:  node omniflow-setup.mjs --push   (commit + push bhi)
 *
 * Ye file kahin bhi rename kar sakte ho (e.g. setup.mjs) — naam se koi farq nahi.
 */
import fs from "node:fs";
import path from "node:path";
import { execFileSync } from "node:child_process";

const WEBSITE_FILES = {
  "app/dashboard/login/page.tsx": "",
  "app/dashboard/forgot-password/page.tsx": "",
  "app/dashboard/reset-password/page.tsx": "",
  "app/api/omniflow/auth/forgot-password/route.ts": "",
  "app/api/omniflow/auth/reset-password/route.ts": "",
  "app/api/omniflow/admin/clients/route.ts": "",
  "app/api/omniflow/admin/clients/[id]/reset-password/route.ts": "",
  "app/admin/(panel)/customers/page.tsx": "",
  "lib/omniflow/forgot-password.ts": "",
  "lib/omniflow/admin-control-plane.ts": ""
};

const BACKEND_FILES = {
  "auth_password_reset.py": "",
  "admin_users.py": "",
  "migrations/007_password_reset_tokens.sql": ""
};

const root = process.cwd();
const doPush = process.argv.slice(2).includes("--push");

const CYAN = "\x1b[36m";
const GREEN = "\x1b[32m";
const YELLOW = "\x1b[33m";
const RED = "\x1b[31m";
const BOLD = "\x1b[1m";
const OFF = "\x1b[0m";

function info(msg) { console.log(CYAN + "==> " + OFF + msg); }
function ok(msg)   { console.log("  " + GREEN + "+" + OFF + " " + msg); }
function warn(msg) { console.log("  " + YELLOW + "!" + OFF + " " + msg); }
function fail(msg) { console.error(RED + "ERROR: " + OFF + msg); process.exit(1); }

// ---------- detection ----------
function detectType(dir) {
  if (fs.existsSync(path.join(dir, "app.py"))) return "backend";
  if (fs.existsSync(path.join(dir, "package.json"))) return "website";
  return null;
}

function findSiblingOf(otherType) {
  const parent = path.dirname(root);
  let hits = [];
  try {
    for (const name of fs.readdirSync(parent)) {
      const p = path.join(parent, name);
      if (p === root) continue;
      let st;
      try { st = fs.statSync(p); } catch { continue; }
      if (!st.isDirectory()) continue;
      if (detectType(p) === otherType) hits.push(p);
    }
  } catch { /* parent not readable */ }
  return hits.length === 1 ? hits[0] : null;
}

// ---------- file writers ----------
function writeFiles(map, label, baseDir) {
  let written = 0;
  let upToDate = 0;
  for (const [rel, b64] of Object.entries(map)) {
    const dest = path.join(baseDir, ...rel.split("/"));
    const content = Buffer.from(b64, "base64");
    if (fs.existsSync(dest)) {
      try {
        if (fs.readFileSync(dest).equals(content)) { upToDate++; continue; }
      } catch { /* fall through and overwrite */ }
    }
    fs.mkdirSync(path.dirname(dest), { recursive: true });
    fs.writeFileSync(dest, content);
    written++;
    ok(label + " " + rel);
  }
  console.log("  (" + written + " nayi, " + upToDate + " pehle se theek)\n");
}

function patchSidebar(dir) {
  const file = path.join(dir, "app", "admin", "components", "AdminSidebar.tsx");
  if (!fs.existsSync(file)) { warn("AdminSidebar.tsx nahi mila (skip)"); return; }
  let s = fs.readFileSync(file, "utf8");
  if (s.includes('href: "/admin/customers"')) { ok("AdminSidebar me Customers link pehle se hai (skip)"); return; }
  const anchor = '{ label: "Leads", href: "/admin/leads", icon: "◇", enabled: true },';
  if (!s.includes(anchor)) { warn("AdminSidebar ka anchor nahi mila — Customers link manually add karein"); return; }
  s = s.replace(anchor, anchor + '\n  { label: "Customers", href: "/admin/customers", icon: "◉", enabled: true },', 1);
  fs.writeFileSync(file, s);
  ok("AdminSidebar: Customers link add ho gaya");
}

function patchAppPy(dir) {
  const file = path.join(dir, "app.py");
  if (!fs.existsSync(file)) { warn("app.py nahi mila (skip)"); return; }
  let s = fs.readFileSync(file, "utf8");
  const hasImports = s.includes("from auth_password_reset import") && s.includes("from admin_users import");
  const hasRegister = s.includes("register_blueprint(auth_password_reset_bp)") && s.includes("register_blueprint(admin_users_bp)");
  if (hasImports && hasRegister) { ok("app.py pehle se patched hai (skip)"); return; }

  let changed = false;
  if (!s.includes("from auth_password_reset import")) {
    const lines = s.split("\n");
    let lastImport = 0;
    for (let i = 0; i < lines.length; i++) if (/^(import |from )/.test(lines[i])) lastImport = i;
    lines.splice(lastImport + 1, 0,
      "from auth_password_reset import bp as auth_password_reset_bp",
      "from admin_users import bp as admin_users_bp");
    s = lines.join("\n");
    changed = true;
    ok("app.py: blueprint imports add ho gaye");
  }
  if (!s.includes("register_blueprint(auth_password_reset_bp)")) {
    const lines = s.split("\n");
    let idx = -1;
    for (let i = 0; i < lines.length; i++) {
      const t = lines[i].trim();
      if (t === "return app" || t.startsWith("return app ")) { idx = i; break; }
    }
    if (idx < 0) {
      warn("app.py me 'return app' nahi mila — yeh 2 lines manually add karein:");
      console.log("     app.register_blueprint(auth_password_reset_bp)");
      console.log("     app.register_blueprint(admin_users_bp)");
    } else {
      lines.splice(idx, 0,
        "    app.register_blueprint(auth_password_reset_bp)",
        "    app.register_blueprint(admin_users_bp)");
      s = lines.join("\n");
      changed = true;
      ok("app.py: dono blueprints register ho gaye");
    }
  }
  if (changed) fs.writeFileSync(file, s);
}

function gitCommitPush(dir, label) {
  if (!fs.existsSync(path.join(dir, ".git"))) { warn(label + " git repo nahi hai (skip push)"); return; }
  try {
    const branch = execFileSync("git", ["branch", "--show-current"], { cwd: dir, encoding: "utf8" }).trim();
    execFileSync("git", ["add", "-A"], { cwd: dir });
    execFileSync("git", ["commit", "-m", "feat: admin client password reset + forgot password flow"], { cwd: dir });
    execFileSync("git", ["push", "origin", branch], { cwd: dir });
    ok(label + ": commit + push ho gaya (" + branch + ")");
  } catch (e) {
    warn(label + ": commit/push fail — khud karein: git add -A && git commit -m \"feat: password reset\" && git push");
  }
}

// ---------- apply one repo ----------
function applyTo(type, dir) {
  info("Repo mila: " + BOLD + type + OFF + "  ->  " + dir);
  console.log("");
  if (type === "website") {
    writeFiles(WEBSITE_FILES, "[website]", dir);
    patchSidebar(dir);
  } else {
    writeFiles(BACKEND_FILES, "[backend]", dir);
    patchAppPy(dir);
  }
}

// ---------- main ----------
const selfType = detectType(root);
if (!selfType) {
  fail("Yeh folder koi OmniFlow repo nahi hai.\n" +
       "   Website root: jahan package.json hai   |   Backend root: jahan app.py hai\n" +
       "   Bas file ko project root mein rakho aur 'node omniflow-setup.mjs' chalao.");
}

const touched = [];
applyTo(selfType, root);
touched.push({ dir: root, type: selfType });

const otherType = selfType === "website" ? "backend" : "website";
const sibling = findSiblingOf(otherType);
if (sibling) {
  console.log(CYAN + "==> " + OFF + "Doosri repo mil gayi (aik hi folder me): " + BOLD + sibling + OFF + "\n");
  applyTo(otherType, sibling);
  touched.push({ dir: sibling, type: otherType });
} else {
  console.log(CYAN + "==> " + OFF + "Doosri repo is folder ke saath nahi mili.\n" +
    "   Us repo ke root mein bhi yehi file rakho aur wahan bhi chalao:\n" +
    "       node omniflow-setup.mjs\n");
}

if (doPush) {
  console.log("");
  for (const t of touched) gitCommitPush(t.dir, "[" + t.type + "]");
}

console.log("\n" + GREEN + "============================================================" + OFF);
console.log("  Sab changes apply ho gaye! Ab 3 chhote steps baqi hain:\n");
console.log("  1. NEON console > SQL Editor > backend repo ki file:");
console.log("     " + BOLD + "migrations/007_password_reset_tokens.sql" + OFF + "  (sirf 1 baar run)");
console.log("  2. VERCEL (dono projects) > Settings > Environment Variables:");
console.log("     " + BOLD + "OMNIFLOW_SERVICE_KEY" + OFF + " = same lambi random string dono jagah");
console.log("  3. Deploy ~2 min wait karo, phir mujhe batao — main verify kar dunga.");
console.log(GREEN + "============================================================" + OFF);
